const unpostedBlockerByKey = `-- name: UnpostedBlockerByKey :one
SELECT u.id, u.source_kind FROM accounting.unposted u
WHERE u.order_key = $1 AND u.posted_at IS NULL AND u.resolved_at IS NULL
  AND NOT (u.source_module = $2 AND u.source_kind = $3
           AND u.source_id = $4 AND u.source_part = $5)
  AND u.id < coalesce((SELECT o.id FROM accounting.unposted o
                       WHERE o.source_module = $2 AND o.source_kind = $3
                         AND o.source_id = $4 AND o.source_part = $5),
                      9223372036854775807)
ORDER BY u.id
LIMIT 1
`

type UnpostedBlockerByKeyParams struct {
	OrderKey     *string
	SourceModule string
	SourceKind   string
	SourceID     int64
	SourcePart   string
}

type UnpostedBlockerByKeyRow struct {
	ID         int64
	SourceKind string
}

// UnpostedBlockerByKey is the row an expense fact waits behind (R2, R15): the
// earliest open row of the same entry or claim that is not its own and was
// recorded before it.
func (q *Queries) UnpostedBlockerByKey(ctx context.Context, arg UnpostedBlockerByKeyParams) (UnpostedBlockerByKeyRow, error) {
	row := q.db.QueryRow(ctx, unpostedBlockerByKey,
		arg.OrderKey,
		arg.SourceModule,
		arg.SourceKind,
		arg.SourceID,
		arg.SourcePart,
	)
	var i UnpostedBlockerByKeyRow
	err := row.Scan(&i.ID, &i.SourceKind)
	return i, err
}

